,54px);line-height:1.05;letter-spacing:-.045em;margin:0}.section-head p{color:var(--muted);max-width:390px;margin:0}.day{position:relative;border-top:1px solid var(--line);padding-left:0}.day:last-child{border-bottom:1px solid var(--line)}.day summary{display:grid;grid-template-columns:55px minmax(240px,1fr) minmax(180px,.6fr) 36px;align-items:center;gap:18px;padding:24px 7px;list-style:none;cursor:pointer;border-radius:10px;transition:background .2s}.day summary::-webkit-details-marker{display:none}.day summary:hover{background:#f4ece6}.day summary:focus-visible,.gallery-arrow:focus-visible,.cta:focus-visible,.nav a:focus-visible{outline:3px solid #c56a55;outline-offset:4px}.day-num{display:grid;place-items:center;width:40px;height:40px;border:1px solid #d8b2a6;border-radius:50%;color:var(--red);font-size:12px;font-weight:800;background:var(--paper);position:relative}.day[open] .day-num{background:var(--red);border-color:var(--red);color:#fff}.day-title{font-size:19px;font-weight:750;line-height:1.3}.day-subtitle{font-size:14px;color:var(--muted)}.plus{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--line);border-radius:50%;font-size:22px;color:var(--red);text-align:center;transition:transform .2s,background .2s}.day[open] .plus{transform:rotate(45deg);background:#f3e5df}.day-content{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.2fr);gap:clamp(24px,5vw,70px);align-items:center;padding:12px 10px 42px 80px;animation:day-reveal .25s ease-out}.day-copy{color:#625b56}.day-copy p:first-child{margin-top:0}.day-copy p{max-width:58ch}.day-copy .overnight{padding:12px 15px;border-left:3px solid var(--red);background:#f4ece6}.day[open] .day-title{color:var(--red)}@keyframes day-reveal{from{opacity:.45;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}.overnight{font-size:14px}.gallery{min-width:0}.gallery-main{position:relative;aspect-ratio:1.35/1;overflow:hidden;background:#eee3dc;border-radius:5px}.gallery-main i