-content{margin-left:0}}@media(max-width:420px){.day summary{grid-template-columns:32px minmax(0,1fr) 30px;gap:8px}.day-num{width:30px;height:30px;font-size:11px}.day-title{font-size:16px}.hero h1{font-size:clamp(40px,12vw,58px)}.gallery-arrow{width:40px;height:40px}.itinerary{padding-left:17px;padding-right:17px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
