<?php foreach($days as $i=>$day): $images=is_array($day['images']??null)?$day['images']:[]; ?><details class="day" <?= $i===0?'open':'' ?>><summary><span class="day-num"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><span class="day-title"><?=page_escape($day['title']??'Étape du voyage')?></span><span class="day-subtitle"><?=page_escape($day['subtitle']??'')?></span><span class="plus">+</span></summary><div class="day-content"><div class="day-copy"><p><?=nl2br(page_escape($day['description']??''))?></p><?php if(!empty($day['overnight'])): ?><p class="overnight"><strong>Nuitée :</strong> <?=page_escape($day['overnight'])?></p><?php endif; ?></div><div class="gallery"><div class="gallery-main" data-gallery><?php if($images): foreach($images as $j=>$img): ?><img class="<?= $j===0?'active':'' ?>" src="<?=page_escape(page_image_src($img['url']??''))?>" alt="<?=page_escape($img['alt']??$day['title']??'Photo du circuit')?>" loading="lazy" decoding="async"><?php endforeach; ?><button type="button" class="gallery-arrow prev" aria-label="Photo précédente">‹</button><button type="button" class="gallery-arrow next" aria-label="Photo suivante">›</button><span class="gallery-count">1 / <?=count($images)?></span><?php else: ?><div class="no-image">Ajoutez des photos depuis l’administration</div><?php endif; ?></div><div class="gallery-caption">Jour <?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?> · <?=page_escape($day['title']??'Étape du voyage')?></div></div></div></details><?php endforeach; ?></section><section class="bottom-cta"><h2>Prêts à imaginer votre voyage ?</h2><p>Parlons de vos envies et construisons ensemble un itinéraire qui vous ressemble.</p><a href="../../index.html#contact">Demander un devis ↗</a></section></main><footer class="footer"><span>MIARADI-TRAVEL · Tour Operator Madagascar</span><span>Voyager autrement, au plus près du territoire.</span></footer>
<script>
document.querySelectorAll('[data-gallery]').forEach((gallery, galleryIndex) => {
  const imgs = [...gallery.querySelectorAll('img')];
  if (!imgs.length) return;
  const prev = gallery.querySelector('.prev');
  const next = gallery.querySelector('.next');
  const count = gallery.querySelector('.gallery-count');
  let index = Math.max(0, imgs.findIndex(img => img.classList.contains('active')));
  gallery.setAttribute('role', 'group');
  gallery.setAttribute('aria-label', 'Galerie photo de l’étape ' + (galleryIndex + 1));
  if (count) count.setAttribute('aria-live', 'polite');
  if (imgs.length < 2) {
    if (prev) prev.hidden = true;
    if (next) next.hidden = true;
  }
  function show(n) {
    index = (n + imgs.length) % imgs.length;
    imgs.forEach((img, i) => {
      img.classList.toggle('active', i === index);
      img.setAttribute('aria-hidden', i === index ? 'false' : 'true');
    });
    if (count) count.textContent = (index + 1) + ' / ' + imgs.length;
  }
  prev?.addEventListener('click', () => show(index - 1));
  next?.addEventListener('click', () => show(index + 1));
  show(index);
});
document.querySelectorAll('details.day').forEach(day => day.addEventListener('toggle', () => {
  if (!day.open) return;
  document.querySelectorAll('details.day').forEach(other => {
    if (other !== day) other.open = false;
  });
}));
</script><?php endif; ?></body></html>